const dataUrl = $json.body.adjunto.base64;
const base64 = dataUrl.includes(',') ? dataUrl.split(',')[1] : dataUrl;
return [{ json: { audioBase64: base64 } }];

const texto = (($json.text) || '').trim();
return [{
  json: {
    mensajeFinal: texto || '[nota de voz]',
    esAudio: true,
    tieneImagen: false,
    imagenBase64: null,
    tieneVideo: false,
  },
}];

const body = $('Webhook').item.json.body;
const adjunto = body.adjunto;
const tieneImagen = !!(adjunto && adjunto.tipo === 'imagen');
const tieneVideo = !!(adjunto && adjunto.tipo === 'video');
let mensajeFinal = body.mensaje || '';
if (!mensajeFinal) {
  mensajeFinal = tieneImagen ? '[imagen adjunta]' : (tieneVideo ? '[video adjunto]' : '');
}

return [{
  json: {
    mensajeFinal,
    esAudio: false,
    tieneImagen,
    imagenBase64: tieneImagen ? adjunto.base64 : null,
    tieneVideo,
  },
}];

return [{
  json: {
    mensajeFinal: $json.mensajeFinal,
    esAudio: $json.esAudio,
    tieneImagen: $json.tieneImagen,
    imagenBase64: $json.imagenBase64,
    tieneVideo: $json.tieneVideo,
  },
}];

return [{
  json: {
    reply: 'Estas escribiendo muy rapido. Espera un momento antes de enviar otro mensaje para que pueda responderte con calma.',
    estado: 'limitado',
  },
}];

const mensaje = $('Preparar guardar mensaje').item.json.mensajeFinal;
const systemPrompt = `Eres un clasificador para Reviive, un taller de restauracion de objetos con valor emocional. Analiza el mensaje del usuario y responde SOLO con un JSON exacto: {"riesgo": "bajo|medio|alto", "motivo_riesgo": "string breve o vacio", "intencion": "pedidos|proveedores|cotizacion|extraccion|acompanamiento"}. Usa riesgo=alto SOLO si el mensaje muestra senales claras de crisis emocional severa, ideas de autolesion, o angustia extrema que requiera atencion humana inmediata -- no por tristeza o nostalgia normal de un duelo. Usa intencion=pedidos si el usuario pregunta por el estado de un pedido u orden existente. Usa intencion=proveedores si el usuario busca un taller o proveedor especifico para su objeto. Usa intencion=cotizacion si el usuario pregunta cuanto podria costar o cuanto tiempo tomaria un servicio. Usa intencion=extraccion si el usuario esta contando por primera vez, con suficiente detalle (que objeto es y que historia/significado tiene), un recuerdo que quiere registrar o guardar en la plataforma. En cualquier otro caso usa intencion=acompanamiento.`;

return [{
  json: {
    openaiPayload: {
      model: 'gpt-4o-mini',
      response_format: { type: 'json_object' },
      temperature: 0,
      max_tokens: 200,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: mensaje },
      ],
    },
  },
}];

const resp = $json;
let riesgo = 'bajo';
let motivo = '';
let intencion = 'acompanamiento';

try {
  if (!resp.error && resp.choices && resp.choices.length) {
    const parsed = JSON.parse(resp.choices[0].message.content);
    if (['bajo', 'medio', 'alto'].includes(parsed.riesgo)) riesgo = parsed.riesgo;
    if (typeof parsed.motivo_riesgo === 'string') motivo = parsed.motivo_riesgo;
    if (['pedidos', 'proveedores', 'cotizacion', 'extraccion', 'acompanamiento'].includes(parsed.intencion)) intencion = parsed.intencion;
  }
} catch (e) {
  // ante cualquier duda, se sigue con el comportamiento por defecto (acompanamiento, riesgo bajo)
}

return [{ json: { riesgo, motivo, intencion } }];

const riesgo = $('Procesar clasificacion').item.json.riesgo;
const intencion = $('Procesar clasificacion').item.json.intencion;
const agente = riesgo === 'alto' ? 'seguridad' : intencion;

const body = {
  conversacion_id: $('Webhook').item.json.body.conversacion_id,
  agente,
  agent_version: 'v1',
};

return [{ json: { bodyString: JSON.stringify(body) } }];

const mensajeSeguridad = 'Gracias por confiar en Reviive para contarme esto. Quiero asegurarme de que estes bien: si sientes que esto es una emergencia o una crisis, por favor contacta a la Linea de la Vida (Colombia) al 192 opcion 4, o acude a un profesional de salud mental de confianza. Estoy aqui para acompanarte con tu recuerdo cuando te sientas lista o listo; tambien avisamos a nuestro equipo humano para que pueda apoyarte.';

return [{
  json: {
    run_id: $('Registrar inicio de agente').item.json.run_id,
    reply: mensajeSeguridad,
    status: 'completado',
    input_tokens: null,
    output_tokens: null,
    evaluation_flags: ['riesgo_emocional'],
    esAudio: $('Preparar guardar mensaje').item.json.esAudio,
  },
}];

const mensaje = $('Preparar guardar mensaje').item.json.mensajeFinal;
const tieneImagen = $('Preparar guardar mensaje').item.json.tieneImagen;
const imagenBase64 = $('Preparar guardar mensaje').item.json.imagenBase64;
const tieneVideo = $('Preparar guardar mensaje').item.json.tieneVideo;
const esAudio = $('Preparar guardar mensaje').item.json.esAudio;
const intencion = $('Procesar clasificacion').item.json.intencion;

const pedidosRaw = ($('Obtener pedidos usuario').item.json.results) || [];
const pedidosResumen = pedidosRaw.slice(0, 3).map((p) => ({
  codigo: p.codigo,
  estado: p.estado,
  objeto: p.resumen && p.resumen.objeto,
}));

const proveedoresRaw = ($('Obtener proveedores validados').item.json.results) || [];
const proveedoresResumen = proveedoresRaw.slice(0, 5).map((p) => ({
  nombre_taller: p.nombre_taller,
  ciudad: p.ciudad,
  calificacion: p.calificacion,
}));

const catalogoRaw = ($('Obtener catalogo').item.json.results) || [];
const catalogoResumen = catalogoRaw.filter((p) => p.activo).slice(0, 8).map((p) => ({
  nombre: p.nombre,
  categoria: p.categoria,
  precio_base: p.precio_base,
}));

let basePrompt = `Eres Alma, la asistente de inteligencia artificial de Reviive, un taller que restaura objetos con valor emocional. Tu tono es calido, cercano, elegante y profesional, nunca frio ni robotico, y nunca te presentas como psicologa ni sustituyes atencion profesional. Nunca confirmes precios ni tiempos de entrega exactos ni inventes estados de pedidos o proveedores: solo puedes mencionar los pedidos reales listados en pedidos_recientes y los proveedores reales listados en proveedores_validados si el usuario pregunta por eso. Si intencion es cotizacion, usa catalogo_precios (precio_base real) para dar un RANGO orientativo y aclara siempre que es una estimacion preliminar, no oficial -- el taller asignado enviara la cotizacion formal. Si no hay datos que respondan la pregunta, dilo con honestidad en vez de inventar.\n\nIntencion detectada: ${intencion}.\npedidos_recientes: ${JSON.stringify(pedidosResumen)}\nproveedores_validados: ${JSON.stringify(proveedoresResumen)}\ncatalogo_precios: ${JSON.stringify(catalogoResumen)}`;

if (tieneImagen) {
  basePrompt += '\n\nEl usuario adjunto una imagen y SI puedes verla: se te entrega dentro del mensaje del usuario como contenido visual real, no como un dato inventado. Observala con atencion y describe con precision lo que hay en ella cuando sea relevante para tu respuesta. Nunca digas que no puedes ver imagenes: eso seria falso.';
}

if (tieneVideo) {
  basePrompt += '\n\nEl usuario adjunto un video. A diferencia de las imagenes, los videos no puedes analizarlos: agradece el envio con honestidad y pidele que te cuente o describa lo que muestra si es relevante para ayudarlo.';
}

let systemPromptFinal = basePrompt + '\n\nResponde siempre en espanol, en 2 a 4 frases.';
let userContent = mensaje;

const openaiPayload = { model: 'gpt-4o-mini', temperature: 0.7, max_tokens: 350, messages: [] };

if (intencion === 'extraccion') {
  systemPromptFinal = basePrompt + `\n\nAdemas, el usuario esta contando la historia de un objeto que quiere registrar como recuerdo. Responde UNICAMENTE con un JSON exacto: {"reply": "tu respuesta calida confirmando que guardaste el recuerdo, 2-3 frases, en espanol", "persona_recordada": "nombre o vinculo si lo menciono, o vacio", "historia": "resumen fiel de la historia contada en 1-3 frases", "objeto": {"tipo": "tipo de objeto", "marca": "o vacio", "anio_aproximado": "o vacio", "material": "o vacio", "estado": "estado/condicion descrita, o vacio"}}. Si el mensaje NO tiene suficiente informacion para extraer un objeto y una historia real, deja historia vacio y en reply pide amablemente el detalle que falta (nunca inventes datos que no dijo el usuario).`;
  openaiPayload.response_format = { type: 'json_object' };
}

if (tieneImagen && imagenBase64) {
  userContent = [
    { type: 'text', text: mensaje || 'Aqui te comparto una foto.' },
    { type: 'image_url', image_url: { url: imagenBase64 } },
  ];
}

openaiPayload.messages = [
  { role: 'system', content: systemPromptFinal },
  { role: 'user', content: userContent },
];

return [{
  json: {
    run_id: $('Registrar inicio de agente').item.json.run_id,
    intencion,
    esAudio,
    openaiPayload,
  },
}];

const resp = $json;
const intencion = $('Preparar prompt Alma').item.json.intencion;
const esAudio = $('Preparar prompt Alma').item.json.esAudio;
let reply, statusValue, inputTokens = null, outputTokens = null, structuredData = null;

if (resp.error || !resp.choices || !resp.choices.length) {
  statusValue = 'fallido';
  reply = 'Estoy teniendo un problema tecnico para responder en este momento. Por favor intenta de nuevo en unos minutos, o cuentame de otra forma en que puedo ayudarte con tu recuerdo.';
} else {
  statusValue = 'completado';
  const contenido = resp.choices[0].message.content.trim();
  if (resp.usage) {
    inputTokens = resp.usage.prompt_tokens;
    outputTokens = resp.usage.completion_tokens;
  }
  if (intencion === 'extraccion') {
    try {
      const parsed = JSON.parse(contenido);
      reply = parsed.reply || 'Gracias por contarme tu historia.';
      if (parsed.historia) {
        structuredData = {
          persona_recordada: parsed.persona_recordada || '',
          historia: parsed.historia,
          objeto: parsed.objeto || {},
        };
      }
    } catch (e) {
      reply = contenido;
    }
  } else {
    reply = contenido;
  }
}

return [{
  json: {
    run_id: $('Preparar prompt Alma').item.json.run_id,
    reply,
    status: statusValue,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    evaluation_flags: [],
    structured_data: structuredData,
    esAudio,
  },
}];

const body = { status: $json.status, reply: $json.reply };
if ($json.input_tokens != null || $json.output_tokens != null) {
  body.metrics = { input_tokens: $json.input_tokens, output_tokens: $json.output_tokens };
}
if ($json.evaluation_flags && $json.evaluation_flags.length) {
  body.evaluation = { flags: $json.evaluation_flags };
}
if ($json.structured_data) {
  body.structured_data = $json.structured_data;
}

return [{ json: { run_id: $json.run_id, reply: $json.reply, status: $json.status, esAudio: $json.esAudio, bodyString: JSON.stringify(body) } }];

const texto = ($json.reply || '').slice(0, 4000);
return [{
  json: {
    conversacion_id: $('Webhook').item.json.body.conversacion_id,
    run_id: $json.run_id,
    reply: $json.reply,
    estado: $json.estado,
    ttsPayload: { model: 'tts-1', voice: 'nova', input: texto || 'Listo.' },
  },
}];

const runId = $json.run_id;
const reply = $json.reply;
const systemPrompt = `Eres un evaluador de calidad para las respuestas del asistente Alma de Reviive. Te dare la respuesta que Alma le dio a un cliente. Califica de 0 a 1 que tan bien cumple: empatia y calidez, no inventar precios/tiempos/estados no confirmados, no presentarse como psicologa ni sustituir atencion profesional. Responde SOLO con un JSON exacto: {"puntaje": <numero entre 0 y 1>, "observaciones": "1 frase breve", "requiere_revision": <true si la respuesta viola alguna regla o es claramente inadecuada, si no false>}.`;

return [{
  json: {
    ejecucion_evaluada: runId,
    openaiPayload: {
      model: 'gpt-4o-mini',
      response_format: { type: 'json_object' },
      temperature: 0,
      max_tokens: 150,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: reply || '' },
      ],
    },
  },
}];

const resp = $json;
let ok = false, puntaje = 0.5, observaciones = '', requiereRevision = false;

try {
  if (!resp.error && resp.choices && resp.choices.length) {
    const parsed = JSON.parse(resp.choices[0].message.content);
    if (typeof parsed.puntaje === 'number') { puntaje = parsed.puntaje; ok = true; }
    observaciones = parsed.observaciones || '';
    requiereRevision = !!parsed.requiere_revision;
  }
} catch (e) {
  // sin evaluacion util; se completa con un puntaje neutro para no dejar el run del evaluador colgado
}

return [{
  json: {
    ejecucion_evaluada: $('Preparar prompt evaluador').item.json.ejecucion_evaluada,
    ok, puntaje, observaciones, requiereRevision,
  },
}];

const body = { agente: 'evaluador', agent_version: 'v1' };
return [{
  json: {
    ejecucion_evaluada: $json.ejecucion_evaluada,
    puntaje: $json.puntaje,
    observaciones: $json.observaciones,
    requiereRevision: $json.requiereRevision,
    bodyString: JSON.stringify(body),
  },
}];

const datos = $('Construir firma evaluador request').item.json;
const body = {
  status: 'completado',
  structured_data: {
    ejecucion_evaluada: datos.ejecucion_evaluada,
    puntaje: datos.puntaje,
    requiere_revision: datos.requiereRevision,
    observaciones: datos.observaciones,
  },
};

return [{ json: { run_id: $('Registrar inicio evaluador').item.json.run_id, bodyString: JSON.stringify(body) } }];
